    const eligible=students.filter(s=>s.status==='approved'),form=el('form'),pick=field(form,'Aluno aprovado','calendar_student','',{options:{'':'Selecione o aluno',...Object.fromEntries(eligible.map(s=>[s.id,s.name+' · '+s.id]))}});pick.required=true;const inner=el('div');form.append(el('button','Agendar aluno neste horário'));form.addEventListener('submit',action(async()=>{await showAvailableAppointments(pick.value,inner,event.id,refresh);inner.scrollIntoView({block:'nearest'})}));record.append(form,inner);if(!eligible.length)record.append(el('p','Não há alunos aprovados disponíveis.'));
