 if(['admin','secretary'].includes(me.role)){if(!$('professionals-area')){const area=el('section',undefined,{id:'professionals-area'});$('team-area').before(area);area.append(el('h2','Psicologia e assistência social'),el('p','Cadastros profissionais, documentos e liberação para oferecer horários.'),el('button','Cadastrar profissional',{id:'professional-new'}),el('div',undefined,{id:'professional-list'}),el('section',undefined,{id:'professional-detail',hidden:'',tabindex:'-1'}));$('professional-new').addEventListener('click',action(()=>professionalDetail(null)))}$('professionals-area').hidden=false;$('professional-new').hidden=!['admin','secretary'].includes(me.role);professionalList().catch(e=>notice(e.message,true))}else if($('professionals-area'))$('professionals-area').hidden=true;
